Object.assign(COLLECTION_INFO.starship,{azimuth:.70,elevation:.10,zoom:.84,basis:'依据SpaceX官网公开的总高124米、直径9米、超重型助推器72米与星舰52米比例，助推器外圈20台、中圈10台、中心3台，星舰3台海平面与3台真空猛禽。为在9米箭体内排下20台外圈发动机，喷管出口取1.14米，与官网1.3米不同。贮箱、襟翼与栅格舵尺寸、隔热瓦排列和设备细部为网页补全，不是飞行构型或制造图纸。'});
Object.assign(COLLECTION_INFO.saturnv,{azimuth:.60,elevation:.12,zoom:.84,basis:'依据NASA公开的S-IC、S-II、S-IVB、仪器舱、指令舱、服务舱、适配段与逃逸塔尺寸，总高与最大箭体直径按110.6426米与10.0584米比例归一化。黑白涂装分区参考非官方整理资料。整流罩、稳定翼外形、内部贮箱与飞船设备为网页补全。'});
Object.assign(COLLECTION_INFO.soyuz,{azimuth:.68,elevation:.23,zoom:.82,basis:'依据ESA联盟TMA资料，服务舱长2.26米，返回舱长2.24米，轨道舱长2.98米，最大直径2.72米，太阳翼跨度10.6米，面积约10平方米。三舱嵌套量、太阳翼单板宽度、座椅、设备、探杆与天线为网页补全。'});
Object.assign(COLLECTION_INFO.dragon,{azimuth:.60,elevation:.30,zoom:.87,basis:'依据SpaceX官网高8.1米、直径4米的比例和NASA商业载人资料中的翻转鼻锥、后备舱半侧太阳能电池与半侧散热器布局。返回舱与后备舱的高度分配、稳定翼片数、座椅与设备为网页补全，不提供推进系统工作参数。'});
Object.assign(COLLECTION_INFO.rov,{azimuth:.63,elevation:.31,zoom:.84,basis:'外廓按MBARI Doc Ricketts公布的12×6×7英尺，机械臂臂展参照TITAN 4的1922 mm。推进器台数与布置、内部设备、工具和灯具数量为通用网页补全，两只机械臂按同一型号绘制，不是该潜水器的原厂CAD或耐压设计。'});
Object.assign(COLLECTION_INFO.excavator,{azimuth:.73,elevation:.35,zoom:.84,basis:'比例取自Caterpillar 320规格书（Reach动臂5.7 m，R2.9斗杆）的滚轮中心距、轨距、履带板宽、回转平台宽、驾驶室高和三种油缸行程。斗杆长度、铲斗连杆尺寸和履带板块数沿用网页既有设定，与规格书不同。油缸与四连杆按本网页几何闭合，不是Cat 320原厂工作装置设计或承载验证。'});
Object.assign(COLLECTION_INFO.locomotive,{azimuth:.55,elevation:.25,zoom:.83,basis:'比例依据BR Standard Class 2 2-6-0（Great Central Railway保存的78018、78019）公开的轮径、轴距、全长、车高和汽缸尺寸。两段动轮间距、轮距和联动杆位置沿用网页既有设定，车宽因此大于原车。锅炉、司机室和煤水车细部为推理补全，未建阀动装置，没有锅炉压力或实物运行验证。'});
