Object.assign(COLLECTION_INFO.landsat9,{zoom:1.0,source:'https://science.nasa.gov/gallery/landsat-diagrams-and-technical-illustrations/',sourceName:'NASA Landsat 图示',tag:'四段单侧太阳翼 · OLI-2 · TIRS-2',basis:'外形参考NASA Landsat 9线框图和Landsat 8/9结构图，太阳翼由根部轭板、半宽首段和三段整板组成，各段宽度按线框图比例换算，并保留八角平台、OLI-2与TIRS-2两台仪器。外罩、入光口、平台下方天线、安装脚与内部几何按网页观察补全。'});
